/**
 * Golden age of Hollywood (1920s to 1950s) clothing and accessories, generated by this project (MIT):
 * the pieces the MakeHuman asset packs don't have.
 *
 * - Cut from base-mesh helpers like the medieval kit (see medieval.ts): trench coat and suspenders.
 *   They bend with the skin under every morph and animation.
 * - Built as new geometry and bound to the body: pearls, earrings, a diamond collar, a feather boa,
 *   a fur stole, a flapper headband and a showgirl's plumed headdress. Jewellery and ropes are
 *   draped on the body (pushed out of the skin and over the convex outline of the chest) and bound
 *   to the same coarse torso samples as the medieval layers, so they move like the clothes under
 *   them; head pieces are bound to the skull, so face animation doesn't bend them.
 *
 * Feathers and fur are alpha-cut cards with textures drawn here (white, so any colour tints them).
 */
import { writeFileSync } from "node:fs";
import { join } from "node:path";
import type { MeshDef, ProxyDef } from "@actors/core";
import { PNG } from "pngjs";
import { BlobWriter } from "./blob";
import { IN, OUT, type Point, has, isArm, isLeg, neckline } from "./garments";
import type { Vec3 } from "./geometry";
import {
  type Landmarks,
  type MedievalContext,
  type MedievalOutput,
  type MedievalSpec,
  bodice,
  buildSpecs,
  landmarks,
  scaleRefsOf,
  shepard,
  skirtTop,
  torsoSamples,
} from "./medieval";

const min = Math.min, max = Math.max;
const clamp01 = (t: number) => max(0, min(1, t));
const smooth = (t: number) => { const s = clamp01(t); return s * s * (3 - 2 * s); };

/** A colour picked by eye (sRGB hex) as the linear values plain garment materials store. */
export function linear(hex: string): [number, number, number] {
  const n = parseInt(hex.replace("#", ""), 16);
  return [16, 8, 0].map((s) => {
    const c = ((n >> s) & 255) / 255;
    return c <= 0.04045 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4;
  }) as [number, number, number];
}

const CLOTHING = "Golden age clothing";
const ACCESSORIES = "Golden age accessories";

/** Trench coat skirt: hem at `t` (hip to ankle), open at the front below the belt. */
const coatSkirt = (m: Landmarks, t: number) => (c: Point) => {
  const hem = min(c.y - m.hem(t), m.pelvis + 0.02 - c.y);
  const front = c.z > m.torso.center[1] ? Math.abs(c.x) - 0.012 : IN;
  return min(hem, front);
};

export const GOLDEN_CUT: MedievalSpec[] = [
  {
    name: "ga-trench-coat", label: "Trench coat", category: CLOTHING, occupies: ["coat"],
    color: linear("#a08a5e"), roughness: 0.8, fabric: "weave", inflate: 0.012, layer: 3.0, hangs: true, hipShare: 0.45,
    pieces: (m) => [
      // Buttoned up, with long sleeves, over a suit or a dress.
      { group: "helper-tights", cut: bodice(m, 0.97, m.pelvis - 0.02, 0.1), offset: (c) => m.torso.pushOut(c, 0.014, 0.35), smoothBind: 0.05, hideSkin: true },
      { group: "helper-skirt", cut: coatSkirt(m, 0.62), offset: (c) => skirtTop(m, c, 0.045, 0.07) },
      {
        // The belt, buckled at the waist.
        group: "helper-tights", minIsland: 4, smoothBind: 0.035,
        cut: (c) => (isArm(c.bone) || isLeg(c.bone) ? OUT : 0.022 - Math.abs(c.y - m.waist + 0.01)),
        offset: (c) => m.torso.pushOut(c, 0.04),
      },
    ],
  },
  {
    name: "ga-suspenders", label: "Suspenders", category: CLOTHING, occupies: ["braces"],
    color: linear("#3a2a20"), roughness: 0.6, fabric: "weave", inflate: 0.007, layer: 2.2,
    pieces: (m) => [
      {
        group: "helper-tights", minIsland: 4,
        cut: (c) => {
          if (isArm(c.bone) && !has(c.bone, "clavicle")) return OUT;
          if (isLeg(c.bone) || has(c.bone, "head", "neck")) return OUT;
          const bottom = c.y - (m.pelvis + 0.05);
          // Straight up the front, over the shoulders, crossing into one strap low on the back.
          const cross = m.waist + 0.08, top = m.neck - 0.03;
          const x = c.z > m.torso.center[1] + 0.01 ? 0.085 : 0.085 * smooth((c.y - cross) / (top - cross));
          return min(bottom, 0.016 - Math.abs(Math.abs(c.x) - x), m.neck + 0.02 - c.y);
        },
        // On the skin, bent with it; the renderer lifts it over the shirt worn under it.
      },
    ],
  },
];

// ---------------------------------------------------------------------------------------------
// Generated pieces: geometry plus a binding per vertex.

type Bind = { refs: number[]; weights: number[]; at: Vec3 };

/** Geometry under construction; each vertex keeps the body binding it moves with. */
class Shape {
  readonly pos: number[] = [];
  readonly uv: number[] = [];
  readonly idx: number[] = [];
  readonly binds: Bind[] = [];
  vertex(p: Vec3, uv: [number, number], bind: Bind): number {
    this.pos.push(...p);
    this.uv.push(...uv);
    this.binds.push(bind);
    return this.binds.length - 1;
  }
  /** A UV sphere (or ellipsoid with radii `r`) around `c`. */
  sphere(c: Vec3, r: Vec3, bind: Bind, seg = 8, rings = 6) {
    const start = this.binds.length;
    for (let i = 0; i <= rings; i++) {
      const a = (i / rings) * Math.PI;
      for (let j = 0; j <= seg; j++) {
        const b = (j / seg) * Math.PI * 2;
        this.vertex([c[0] + r[0] * Math.sin(a) * Math.cos(b), c[1] + r[1] * Math.cos(a), c[2] + r[2] * Math.sin(a) * Math.sin(b)], [j / seg, i / rings], bind);
      }
    }
    for (let i = 0; i < rings; i++)
      for (let j = 0; j < seg; j++) {
        const k = start + i * (seg + 1) + j;
        this.idx.push(k, k + seg + 1, k + 1, k + 1, k + seg + 1, k + seg + 2);
      }
  }
  /** A bent card along `spine` (points), `width` wide across `side`; v runs along the spine. */
  card(spine: Vec3[], side: Vec3[], width: number[], bind: Bind) {
    const start = this.binds.length;
    spine.forEach((p, i) => {
      const v = i / (spine.length - 1);
      for (const s of [-0.5, 0.5]) this.vertex(add(p, scale(side[i], s * width[i])), [s + 0.5, v], bind);
    });
    for (let i = 0; i + 1 < spine.length; i++) {
      const k = start + i * 2;
      this.idx.push(k, k + 1, k + 2, k + 1, k + 3, k + 2);
    }
  }
  /** A tube of radius `r[i]` along a path (closed or open). */
  tube(path: Vec3[], r: number[], binds: Bind[], sides = 8, closed = false) {
    const start = this.binds.length;
    const frames = pathFrames(path, closed);
    path.forEach((p, i) => {
      const [, n, b] = frames[i];
      for (let j = 0; j <= sides; j++) {
        const a = (j / sides) * Math.PI * 2;
        this.vertex(add(p, add(scale(n, Math.cos(a) * r[i]), scale(b, Math.sin(a) * r[i]))), [j / sides, i / (path.length - 1)], binds[i]);
      }
    });
    const rows = closed ? path.length : path.length - 1;
    for (let i = 0; i < rows; i++)
      for (let j = 0; j < sides; j++) {
        const a = start + i * (sides + 1) + j, b = start + ((i + 1) % path.length) * (sides + 1) + j;
        this.idx.push(a, b, a + 1, a + 1, b, b + 1);
      }
  }
}

const add = (a: Vec3, b: Vec3): Vec3 => [a[0] + b[0], a[1] + b[1], a[2] + b[2]];
const sub = (a: Vec3, b: Vec3): Vec3 => [a[0] - b[0], a[1] - b[1], a[2] - b[2]];
const scale = (a: Vec3, s: number): Vec3 => [a[0] * s, a[1] * s, a[2] * s];
const dot = (a: Vec3, b: Vec3) => a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
const cross = (a: Vec3, b: Vec3): Vec3 => [a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0]];
const len = (a: Vec3) => Math.hypot(a[0], a[1], a[2]);
const norm = (a: Vec3): Vec3 => scale(a, 1 / (len(a) || 1));
const lerp = (a: Vec3, b: Vec3, t: number): Vec3 => [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t];

/** Tangent, normal and binormal along a path (parallel transport, no twisting). */
function pathFrames(path: Vec3[], closed: boolean): [Vec3, Vec3, Vec3][] {
  const n = path.length;
  const tangent = (i: number) => {
    const a = closed ? path[(i - 1 + n) % n] : path[max(0, i - 1)];
    const b = closed ? path[(i + 1) % n] : path[min(n - 1, i + 1)];
    return norm(sub(b, a));
  };
  const out: [Vec3, Vec3, Vec3][] = [];
  let t = tangent(0);
  let nrm = norm(cross(t, Math.abs(t[1]) < 0.9 ? [0, 1, 0] : [1, 0, 0]));
  for (let i = 0; i < n; i++) {
    const t1 = tangent(i);
    nrm = norm(sub(nrm, scale(t1, dot(nrm, t1))));
    t = t1;
    out.push([t, nrm, cross(t, nrm)]);
  }
  return out;
}

/** Points every `step` meters along a polyline. */
function resample(path: Vec3[], step: number, closed = false): Vec3[] {
  const pts = closed ? [...path, path[0]] : path;
  const out: Vec3[] = [pts[0]];
  let carry = 0;
  for (let i = 0; i + 1 < pts.length; i++) {
    const d = len(sub(pts[i + 1], pts[i]));
    let s = step - carry;
    while (s <= d) {
      out.push(lerp(pts[i], pts[i + 1], s / d));
      s += step;
    }
    carry = d - (s - step);
  }
  if (closed && len(sub(out[out.length - 1], out[0])) < step * 0.5) out.pop();
  return out;
}

/** The body surface (skin vertices and normals) near a set of bones, for draping. */
class Surface {
  private readonly grid = new Map<string, number[]>();
  private static readonly CELL = 0.03;
  constructor(private readonly P: number[], private readonly N: Float32Array, private readonly verts: number[]) {
    for (const v of verts) {
      const key = this.key(P[v * 3], P[v * 3 + 1], P[v * 3 + 2]);
      const list = this.grid.get(key);
      list ? list.push(v) : this.grid.set(key, [v]);
    }
  }
  private key(x: number, y: number, z: number, dx = 0, dy = 0, dz = 0) {
    const c = Surface.CELL;
    return `${Math.floor(x / c) + dx},${Math.floor(y / c) + dy},${Math.floor(z / c) + dz}`;
  }
  nearest(p: Vec3): number {
    let best = -1, bd = Infinity;
    for (let ring = 1; ring <= 4 && best < 0; ring++)
      for (let dx = -ring; dx <= ring; dx++)
        for (let dy = -ring; dy <= ring; dy++)
          for (let dz = -ring; dz <= ring; dz++)
            for (const v of this.grid.get(this.key(p[0], p[1], p[2], dx, dy, dz)) ?? []) {
              const d = (this.P[v * 3] - p[0]) ** 2 + (this.P[v * 3 + 1] - p[1]) ** 2 + (this.P[v * 3 + 2] - p[2]) ** 2;
              if (d < bd) { bd = d; best = v; }
            }
    if (best < 0) for (const v of this.verts) {
      const d = (this.P[v * 3] - p[0]) ** 2 + (this.P[v * 3 + 1] - p[1]) ** 2 + (this.P[v * 3 + 2] - p[2]) ** 2;
      if (d < bd) { bd = d; best = v; }
    }
    return best;
  }
  /** Signed height of p over the skin (along the nearest skin normal) and that normal. */
  height(p: Vec3): [number, Vec3] {
    const v = this.nearest(p);
    const n: Vec3 = [this.N[v * 3], this.N[v * 3 + 1], this.N[v * 3 + 2]];
    return [dot(sub(p, [this.P[v * 3], this.P[v * 3 + 1], this.P[v * 3 + 2]]), n), n];
  }
  /** Moves p out until it is at least `gap` above the skin. */
  pushOut(p: Vec3, gap: number, passes = 4): Vec3 {
    let q = p;
    for (let k = 0; k < passes; k++) {
      const [d, n] = this.height(q);
      if (d >= gap - 1e-4) break;
      q = add(q, scale(n, gap - d));
    }
    return q;
  }
  /** Comes in from `from` along `dir` (towards the body) and stops `gap` above the skin. */
  marchIn(from: Vec3, dir: Vec3, gap: number): Vec3 {
    let q = from;
    for (let s = 0; s < 400; s++) {
      const next = add(q, scale(dir, 0.002));
      if (this.height(next)[0] < gap) return q;
      q = next;
    }
    return q;
  }
}

function vertexNormals(P: number[], faces: { v: number[] }[]): Float32Array {
  const N = new Float32Array(P.length);
  for (const f of faces)
    for (let i = 1; i + 1 < f.v.length; i++) {
      const [a, b, c] = [f.v[0], f.v[i], f.v[i + 1]];
      const pa: Vec3 = [P[a * 3], P[a * 3 + 1], P[a * 3 + 2]];
      const n = cross(sub([P[b * 3], P[b * 3 + 1], P[b * 3 + 2]], pa), sub([P[c * 3], P[c * 3 + 1], P[c * 3 + 2]], pa));
      for (const v of [a, b, c]) for (let k = 0; k < 3; k++) N[v * 3 + k] += n[k];
    }
  for (let v = 0; v < N.length / 3; v++) {
    const l = Math.hypot(N[v * 3], N[v * 3 + 1], N[v * 3 + 2]) || 1;
    for (let k = 0; k < 3; k++) N[v * 3 + k] /= l;
  }
  return N;
}

/** Laplacian smoothing of a path (ends stay put on open paths). */
function smoothPath(path: Vec3[], passes: number, closed: boolean): Vec3[] {
  let p = path;
  for (let k = 0; k < passes; k++)
    p = p.map((x, i) => {
      if (!closed && (i === 0 || i === p.length - 1)) return x;
      const a = p[(i - 1 + p.length) % p.length], b = p[(i + 1) % p.length];
      return lerp(x, scale(add(a, b), 0.5), 0.5);
    });
  return p;
}

interface Kit {
  mc: MedievalContext;
  m: Landmarks & { eyes: Vec3 };
  torso: Surface;
  head: Surface;
  /** Skull anchors: head-bound pieces move rigidly with them (not with the face rig). */
  skull: Bind;
  /** Torso binding of a point (shared coarse samples, like the medieval layers). */
  bindTorso: (p: Vec3) => Bind;
  /** Neck base (front of the throat, at the collarbones) and its back. */
  neck: Vec3;
  headTop: number;
  headCenter: Vec3;
  ears: [number, number];
}

/**
 * Lets a chain of beads hang on the body: gravity, fixed bead spacing, `pinned` beads held in place, and the skin and the chest's convex
 * outline pushing it out to `gap`.
 */
function hang(k: Kit, init: Vec3[], pinned: boolean[], closed: boolean, gap: number, step: number): Vec3[] {
  const { m } = k;
  const n = init.length;
  // Free beads sit `step` apart, whatever the starting shape's spacing.
  const rest = init.map((p, i) => (pinned[i] && pinned[(i + 1) % n] ? len(sub(init[(i + 1) % n], p)) : step));
  const p = init.map((x) => [...x] as Vec3), prev = init.map((x) => [...x] as Vec3);
  const g: Vec3 = scale([0, -9.8, 0], (1 / 120) ** 2);
  const collide = (q: Vec3): Vec3 => {
    let r = k.torso.pushOut(q, gap, 2);
    if (r[1] < m.chest + 0.06 && r[2] > m.torso.center[1]) r = add(r, m.drape.pushOut({ x: r[0], y: r[1], z: r[2] }, gap * 0.7));
    return r;
  };
  for (let step = 0; step < 360; step++) {
    for (let i = 0; i < n; i++) {
      if (pinned[i]) continue;
      const v = scale(sub(p[i], prev[i]), 0.94);
      prev[i] = p[i];
      p[i] = add(add(p[i], v), g);
    }
    for (let it = 0; it < 12; it++) {
      for (let i = 0; i < (closed ? n : n - 1); i++) {
        const j = (i + 1) % n;
        const d = sub(p[j], p[i]), l = len(d) || 1e-9;
        const corr = scale(d, (l - rest[i]) / l);
        if (pinned[i] && pinned[j]) continue;
        if (pinned[i]) p[j] = sub(p[j], corr);
        else if (pinned[j]) p[i] = add(p[i], corr);
        else { p[i] = add(p[i], scale(corr, 0.5)); p[j] = sub(p[j], scale(corr, 0.5)); }
      }
      for (let i = 0; i < n; i++) if (!pinned[i]) p[i] = collide(p[i]);
    }
  }
  return p;
}

/** Points round the back of the neck (from angle a0 to a1, 0 = front), `gap` above the skin at height `y`, coming in from radius `r0` (inside the shoulders). */
function backArc(k: Kit, a0: number, a1: number, y: number, gap: number, step: number, r0: number): Vec3[] {
  const [, , z] = k.neck;
  const pts: Vec3[] = [];
  for (let i = 0; i <= 48; i++) {
    const a = a0 + ((a1 - a0) * i) / 48;
    const dir: Vec3 = [Math.sin(a), 0, Math.cos(a)];
    pts.push(k.torso.marchIn(add([0, y, z], scale(dir, r0)), scale(dir, -1), gap));
  }
  return resample(smoothPath(pts, 4, false), step);
}

/** A hanging part of `count` beads: from `start` forward and down through `via` (in front of the body). */
function hangingEnd(start: Vec3, via: Vec3[], count: number): Vec3[] {
  const pts = [start, ...via];
  const total = pts.slice(1).reduce((s, p, i) => s + len(sub(p, pts[i])), 0);
  return resample(pts, total / count).slice(1, count + 1);
}

/** Necklace: pinned round the back of the neck, the front hanging `drop` below the neck base. */
function necklace(k: Kit, drop: number, gap: number, step: number): Vec3[] {
  const [, y] = k.neck;
  const back = backArc(k, Math.PI * 0.55, Math.PI * 1.45, y + 0.025, gap, step, 0.11);
  const l = back[back.length - 1], r = back[0];
  // Long enough to hang `drop` below the neck base at the front.
  const count = Math.round((2 * drop * 1.08 + Math.abs(l[0] - r[0])) / step) - 1;
  const front = hangingEnd(l, [[l[0] * 0.8, y - drop * 0.7, 0.32], [0, y - drop, 0.34], [r[0] * 0.8, y - drop * 0.7, 0.32], r], count + 1);
  front.pop();
  const init = [...back, ...front];
  return hang(k, init, init.map((_, i) => i < back.length), true, gap, step);
}

/** Rope round the back of the neck and over the shoulders, both ends hanging down the front to `endY`. */
function rope(k: Kit, spread: number, endY: number, endX: number, gap: number, step: number, r0: number): Vec3[] {
  const [, y] = k.neck;
  const back = backArc(k, Math.PI * (0.5 - spread), Math.PI * (1.5 + spread), y + 0.015, gap, step, r0);
  const r = back[0], l = back[back.length - 1];
  const count = Math.round(((y - endY) * 1.1) / step);
  const endL = hangingEnd(l, [[endX * Math.sign(l[0] || 1), (l[1] + endY) / 2, 0.3], [endX * Math.sign(l[0] || 1), endY, 0.3]], count);
  const endR = hangingEnd(r, [[endX * Math.sign(r[0] || -1), (r[1] + endY) / 2, 0.3], [endX * Math.sign(r[0] || -1), endY, 0.3]], count);
  const init = [...endR.reverse(), ...back, ...endL];
  return hang(k, init, init.map((_, i) => i >= endR.length && i < endR.length + back.length), false, gap, step);
}

function strand(shape: Shape, k: Kit, path: Vec3[], r: number) {
  for (const p of path) shape.sphere(p, [r, r, r], k.bindTorso(p), 8, 6);
}

/** A fluffy rope: core tube plus cards of `texture` tufts sticking out all round. */
function fluffyRope(shape: Shape, k: Kit, path: Vec3[], core: number, tuft: number, perStep: number, seed: number, wide = 0.8) {
  const rand = rng(seed);
  const binds = path.map((p) => k.bindTorso(p));
  // The core sits inside the tufts and only hides what is behind it.
  shape.tube(path, path.map(() => core), binds, 8, false);
  const frames = pathFrames(path, false);
  path.forEach((p, i) => {
    const [t, n, b] = frames[i];
    for (let c = 0; c < perStep; c++) {
      const a = rand() * Math.PI * 2;
      const out = norm(add(add(scale(n, Math.cos(a)), scale(b, Math.sin(a))), scale(t, (rand() - 0.5) * 0.8)));
      const l = tuft * (0.7 + rand() * 0.6);
      const base = add(p, scale(out, core * 0.5));
      const spine = [0, 0.5, 1].map((s) => add(add(base, scale(out, l * s)), scale([0, -1, 0], l * s * s * 0.25)));
      const side = norm(cross(out, t));
      shape.card(spine, [side, side, side], [l * wide * 0.9, l * wide * 1.1, l * wide], binds[i]);
    }
  });
}

/** A feather (ostrich plume): two crossed cards along a curved spine. */
function plume(shape: Shape, base: Vec3, dir: Vec3, bend: Vec3, length: number, width: number, bind: Bind) {
  const spine: Vec3[] = [];
  for (let i = 0; i <= 8; i++) {
    const s = i / 8;
    spine.push(add(add(base, scale(dir, length * s)), scale(bend, length * s * s * 0.35)));
  }
  const tangents = spine.map((_, i) => norm(sub(spine[min(8, i + 1)], spine[max(0, i - 1)])));
  const widths = spine.map((_, i) => width * (0.25 + 0.75 * Math.sin(Math.PI * min(1, (i / 8) * 0.9 + 0.1))));
  const across = norm(cross(dir, bend));
  for (const s of [across, norm(cross(dir, across))]) {
    const sides = tangents.map((t) => norm(sub(s, scale(t, dot(s, t)))));
    shape.card(spine, sides, widths, bind);
  }
}

/** Small deterministic random numbers. */
function rng(seed: number) {
  let s = seed >>> 0 || 1;
  return () => ((s = (s * 1664525 + 1013904223) >>> 0) / 4294967296);
}

/** Head ring (band) at the brow, `gap` above the skin at the back and sides (for the hair). */
function headRing(k: Kit, frontGap: number, backGap: number, lift = 0): { ring: Vec3[]; out: Vec3[] } {
  const { m } = k;
  const c = k.headCenter;
  const yFront = m.eyes[1] + 0.05 + lift, yBack = yFront - 0.02;
  const ring: Vec3[] = [];
  const out: Vec3[] = [];
  for (let i = 0; i < 72; i++) {
    const a = (i / 72) * Math.PI * 2;
    const front = (1 + Math.cos(a)) / 2;
    const dir: Vec3 = [Math.sin(a), 0, Math.cos(a)];
    const from: Vec3 = [0.25 * dir[0], yBack + (yFront - yBack) * front, c[2] + 0.25 * dir[2]];
    ring.push(k.head.marchIn(from, scale(dir, -1), backGap + (frontGap - backGap) * smooth((front - 0.6) / 0.3)));
  }
  const sm = smoothPath(ring, 6, true);
  sm.forEach((p) => out.push(norm([p[0] - c[0], 0, p[2] - c[2]])));
  return { ring: sm, out };
}

/** A flat band (ribbon) round a closed ring, `h` tall and `t` thick. */
function band(shape: Shape, ring: Vec3[], outward: Vec3[], h: number, t: number, bind: Bind) {
  const corners: [number, number][] = [[-0.5, 0], [0.5, 0], [0.5, 1], [-0.5, 1], [-0.5, 0]];
  const start = shape.binds.length;
  ring.forEach((p, i) => {
    for (const [dy, dt] of corners) shape.vertex(add(add(p, [0, dy * h, 0]), scale(outward[i], dt * t)), [i / ring.length, dy + 0.5], bind);
  });
  const n = ring.length, w = corners.length;
  for (let i = 0; i < n; i++)
    for (let j = 0; j < w - 1; j++) {
      const a = start + i * w + j, b = start + ((i + 1) % n) * w + j;
      shape.idx.push(a, b, a + 1, a + 1, b, b + 1);
    }
}

export interface GeneratedSpec {
  name: string;
  label: string;
  occupies: string[];
  gender?: "female" | "male";
  color: [number, number, number];
  roughness: number;
  fabric: string;
  layer: number;
  /** Texture drawn by this module (alpha-cut cards). */
  texture?: "feather" | "fur";
  build: (shape: Shape, k: Kit) => void;
}

