/** Builds the golden age pieces: helper cuts plus generated jewellery, ropes and headwear. */
export function buildGoldenAge(mc: MedievalContext, out: string): MedievalOutput {
  const result = buildSpecs(mc, GOLDEN_CUT);
  const P = mc.positions;
  const m = landmarks(mc);
  const bodyFaces = mc.facesOf("body");
  const N = vertexNormals(P, bodyFaces);
  const bodyVerts = [...new Set(bodyFaces.flatMap((f) => f.v))];
  const torsoVerts = bodyVerts.filter((v) => {
    const b = mc.dominantBone(v);
    return has(b, "pelvis", "spine", "neck", "clavicle") || (has(b, "head") && P[v * 3 + 1] < m.neck + 0.08);
  });
  const headVerts = bodyVerts.filter((v) => has(mc.dominantBone(v), "head"));
  // Skull anchors (top and both sides), averaged: rigid with the head, unmoved by the face rig.
  const extreme = (axis: number, sign: number) => headVerts.reduce((a, v) => (P[v * 3 + axis] * sign > P[a * 3 + axis] * sign ? v : a), headVerts[0]);
  const anchors = [extreme(1, 1), extreme(0, 1), extreme(0, -1)];
  const at = [0, 1, 2].map((c) => anchors.reduce((s, v) => s + P[v * 3 + c], 0) / 3) as Vec3;
  const samples = torsoSamples(mc, 0.05);
  const neckJoint = mc.joint("neck_01");
  const headZ = headVerts.map((v) => P[v * 3 + 2]);
  // Ear lobes: the outermost skin at the lower ear, then the lowest point near it.
  const ears = [1, -1].map((s) => {
    const y = m.eyes[1] - 0.03;
    const band = headVerts.filter((v) => Math.abs(P[v * 3 + 1] - y) < 0.012);
    const outer = band.reduce((a, v) => (P[v * 3] * s > P[a * 3] * s ? v : a), band[0]);
    const near = headVerts.filter((v) => Math.hypot(P[v * 3 + 1] - P[outer * 3 + 1], P[v * 3 + 2] - P[outer * 3 + 2]) < 0.035 && P[v * 3] * s > P[outer * 3] * s - 0.012);
    return near.reduce((a, v) => (P[v * 3 + 1] < P[a * 3 + 1] ? v : a), outer);
  }) as [number, number];
  const kit: Kit = {
    mc,
    m,
    torso: new Surface(P, N, torsoVerts),
    head: new Surface(P, N, headVerts),
    skull: { refs: anchors, weights: [1 / 3, 1 / 3, 1 / 3], at },
    bindTorso: (p) => {
      const s = shepard(P, samples, p);
      return { refs: s.refs, weights: s.weights, at: p };
    },
    neck: [0, neckJoint[1] - 0.01, neckJoint[2]],
    headTop: P[anchors[0] * 3 + 1],
    headCenter: [0, (m.eyes[1] + P[anchors[0] * 3 + 1]) / 2, (Math.min(...headZ) + Math.max(...headZ)) / 2],
    ears,
  };
  const textures = new Set<string>();
  for (const spec of GOLDEN_GENERATED) {
    const shape = new Shape();
    spec.build(shape, kit);
    const writer = new BlobWriter();
    const file = `garments/${spec.name}.bin`;
    const n = shape.binds.length;
    const refs: number[] = [], weights: number[] = [], offsets: number[] = [];
    shape.binds.forEach((b, i) => {
      refs.push(...b.refs);
      weights.push(...b.weights);
      for (let c = 0; c < 3; c++) offsets.push(shape.pos[i * 3 + c] - b.refs.reduce((s, r, j) => s + b.weights[j] * P[r * 3 + c], 0));
    });
    const used = [...new Set(refs)];
    const proxy: ProxyDef = {
      name: spec.name,
      vertexCount: n,
      refs: writer.add("u32", refs),
      weights: writer.add("f32", weights),
      offsets: writer.add("f32", offsets),
      scaleRefs: scaleRefsOf(P, used.length >= 2 ? used : bodyVerts),
      blob: file,
    };
    const texture = spec.texture ? `textures/ga-${spec.texture}.png` : undefined;
    if (texture && !textures.has(texture)) {
      writeFileSync(join(out, texture), spec.texture === "feather" ? featherPng() : furPng());
      textures.add(texture);
    }
    const mesh: MeshDef = {
      name: spec.name,
      source: { kind: "proxy", proxy: spec.name },
      role: "garment",
      optional: true,
      blob: file,
      material: { kind: "cloth", color: spec.color, roughness: spec.roughness },
      ...(texture ? { textures: { color: texture } } : {}),
      // Draped clear of the clothes at import; "solid" keeps the renderer from lifting (swelling) them.
      tags: [`fabric:${spec.fabric}`, `layer:${spec.layer}`, "solid"],
      baseIndex: writer.add("u32", Array.from({ length: n }, (_, i) => i)),
      uv: writer.add("f32", shape.uv),
      indices: writer.add("u32", shape.idx),
    };
    result.proxies.push(proxy);
    result.meshes.push(mesh);
    result.files.push({ file, data: writer.toBuffer() });
    result.labels[spec.name] = spec.label;
    result.info[spec.name] = { label: spec.label, category: ACCESSORIES, occupies: spec.occupies, ...(spec.gender ? { gender: spec.gender } : {}), credit: "Actors procedural garment (MIT)" };
  }
  return result;
}

// ---------------------------------------------------------------------------------------------
// Textures (white with alpha; tinted by the garment colour).

/** Ostrich plume: a thin shaft with long, soft, wavy barbs (u across, v from base to tip). */
export function featherPng(): Buffer {
  const w = 128, h = 512;
  const alpha = new Float32Array(w * h), shade = new Float32Array(w * h).fill(1);
  const rand = rng(5);
  const plot = (x: number, y: number, a: number, s: number) => {
    const xi = Math.round(x), yi = Math.round(y);
    if (xi < 0 || xi >= w || yi < 0 || yi >= h) return;
    const i = yi * w + xi;
    if (a > alpha[i]) { alpha[i] = a; shade[i] = s; }
  };
  for (let b = 0; b < 1600; b++) {
    const v0 = rand() * 0.97;
    const side = rand() < 0.5 ? -1 : 1;
    // Widest a little above the middle; short barbs at the base and the tip.
    const reach = (0.18 + 0.32 * Math.sin(Math.PI * min(1, v0 * 1.05))) * (0.75 + rand() * 0.25);
    const rise = 0.06 + rand() * 0.08, wave = rand() * 6, droop = 0.02 + rand() * 0.05;
    for (let s = 0; s <= 1; s += 1 / 90) {
      const u = 0.5 + side * reach * s;
      const v = v0 + rise * s - droop * s * s + Math.sin(s * 9 + wave) * 0.006;
      plot(u * (w - 1), v * (h - 1), 1 - s * 0.55, 0.82 + 0.18 * s);
    }
  }
  for (let y = 0; y < h * 0.98; y++) for (let dx = -1; dx <= 1; dx++) plot(w / 2 + dx, y, 1, 0.75);
  return rgbaPng(w, h, alpha, shade);
}

/** Fur tufts: dense hairs from the root (v = 0) to soft tips. */
export function furPng(): Buffer {
  const w = 128, h = 128;
  const alpha = new Float32Array(w * h), shade = new Float32Array(w * h).fill(1);
  const rand = rng(9);
  for (let k = 0; k < 260; k++) {
    const x0 = rand() * w, l = 0.55 + rand() * 0.45, lean = (rand() - 0.5) * 0.35, curl = (rand() - 0.5) * 0.15;
    for (let s = 0; s <= l; s += 1 / h) {
      const x = Math.round(x0 + (lean * s + curl * s * s) * w), y = Math.round(s * (h - 1));
      if (x < 0 || x >= w) continue;
      const i = y * w + x, a = 1 - (s / l) ** 2 * 0.6;
      if (a > alpha[i]) { alpha[i] = a; shade[i] = 0.7 + 0.3 * (s / l); }
    }
  }
  // Solid at the root, where the tuft meets the stole.
  for (let y = 0; y < h * 0.12; y++) for (let x = 0; x < w; x++) { alpha[y * w + x] = 1; shade[y * w + x] = 0.7; }
  return rgbaPng(w, h, alpha, shade);
}

function rgbaPng(w: number, h: number, alpha: Float32Array, shade: Float32Array): Buffer {
  const png = new PNG({ width: w, height: h });
  // Drawn with v = 0 in row 0; images are stored top row first and v = 0 is the bottom row.
  for (let y = 0; y < h; y++)
    for (let x = 0; x < w; x++) {
      const i = y * w + x, o = ((h - 1 - y) * w + x) * 4;
      const g = Math.round(255 * shade[i]);
      png.data[o] = g;
      png.data[o + 1] = g;
      png.data[o + 2] = g;
      png.data[o + 3] = Math.round(255 * clamp01(alpha[i]));
    }
  return PNG.sync.write(png);
}
